export type GridNavDirection = 'up' | 'down' | 'left' | 'right' | 'pageUp' | 'pageDown';

/**
 * Computes the next highlighted index in a 2-column row-major grid (`[0][1]`, `[2][3]`, ...):
 * - `left` / `right`: steps horizontally by `-1` / `+1` (clamped to `[0, length - 1]`).
 * - `up`: steps vertically by `-2` within the same column (stays put on top row `0`).
 * - `down`: steps vertically by `+2` within the same column (snaps to `length - 1` when stepping
 *   down from the right column onto an odd-length final row; stays put on the bottom row).
 * - `pageUp` / `pageDown`: steps vertically by `5` rows (`±10` indices).
 */
export function stepTwoColumnGridIndex(
  currentIndex: number,
  length: number,
  move: number | GridNavDirection
): number {
  if (length <= 0) {
    return 0;
  }
  const cur = Math.max(0, Math.min(length - 1, currentIndex));
  if (typeof move === 'number') {
    return Math.max(0, Math.min(length - 1, cur + move));
  }
  switch (move) {
    case 'left':
      return Math.max(0, cur - 1);
    case 'right':
      return Math.min(length - 1, cur + 1);
    case 'up':
      return cur - 2 >= 0 ? cur - 2 : cur;
    case 'down': {
      const curRow = Math.floor(cur / 2);
      const lastRow = Math.floor((length - 1) / 2);
      if (curRow >= lastRow) {
        return cur;
      }
      return cur + 2 < length ? cur + 2 : length - 1;
    }
    case 'pageUp': {
      if (cur - 10 >= 0) {
        return cur - 10;
      }
      const topSameCol = cur % 2;
      return topSameCol < length ? topSameCol : 0;
    }
    case 'pageDown': {
      if (cur + 10 < length) {
        return cur + 10;
      }
      const lastRowStart = Math.floor((length - 1) / 2) * 2;
      const bottomSameCol = lastRowStart + (cur % 2);
      return bottomSameCol < length ? bottomSameCol : length - 1;
    }
  }
}

