  public getFormattedSoulModalRows(world: GameWorld): FormattedSoulModalRow[] {
    const absorbed = world.player.absorbedSouls;
    if (absorbed.length === 0) {
      this.selectedSoulIndex = 0;
      return [];
    }
    this.selectedSoulIndex = Math.max(0, Math.min(absorbed.length - 1, this.selectedSoulIndex));
    const rows: FormattedSoulModalRow[] = [];
    absorbed.forEach((entry, idx) => {
      const soul = getSoulById(entry.soulId);
      if (!soul) {
        return;
      }
      rows.push({
        soulId: soul.soulId,
        spriteKey: soul.spriteKey,
        label: getLocalizedSoulName(soul, this.currentLanguage),
        effectBadge: getLocalizedSoulEffectSummary(soul, this.currentLanguage),
        selected: idx === this.selectedSoulIndex,
      });
    });
    return rows;
  }

