  private renderInventorySubTabsBar(world: GameWorld): void {
    const tabsEl = this.config.itemModalTabsEl;
    if (!tabsEl) {
      return;
    }
    if (this.activeModal !== 'inventory') {
      tabsEl.classList.add('hidden');
      return;
    }
    tabsEl.classList.remove('hidden');
    if (typeof document === 'undefined') {
      return;
    }
    tabsEl.innerHTML = '';
    const t = TRANSLATIONS[this.currentLanguage];
    const headerTabs = this.getFormattedInventoryHeaderTabs(world);
    for (const tab of headerTabs) {
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.className = tab.active ? 'item-subtab-btn active' : 'item-subtab-btn';
      btn.dataset.subtab = tab.id;
      btn.textContent = tab.label;
      btn.addEventListener('click', () => {
        if (this.inventorySubTab !== tab.id) {
          this.switchInventorySubTab(world, tab.id);
          this.config.onModalStateChange?.();
        }
      });
      tabsEl.appendChild(btn);
    }
    const hint = document.createElement('span');
    hint.className = 'item-subtab-hint';
    hint.textContent = t.itemModalsUI.subTabSwitchHint;
    tabsEl.appendChild(hint);
  }

