  public get skillHotkeys(): Readonly<Partial<Record<HotkeySlot, BoundSkillHotkey>>> {
    return { ...this._skillHotkeys };
  }

  public getSkillHotkey(slot: HotkeySlot): BoundSkillHotkey | undefined {
    return this._skillHotkeys[slot];
  }

  public getHotkeyForSkill(
    category: ProactiveSkillCategory,
    skillId: string
  ): HotkeySlot | null {
    for (const slot of ORDERED_HOTKEY_SLOTS) {
      const bound = this._skillHotkeys[slot];
      if (bound && bound.category === category && bound.skillId === skillId) {
        return slot;
      }
    }
    return null;
  }

  /**
   * Strict `1-to-1` hotkey toggle/rebind across War & Magic skills (`0`–`9`):
   * - Pressing `slot` on a skill already bound to `slot` unbinds `slot` (`'unbound'`).
   * - Pressing `slot` on a skill bound to another key moves that skill to `slot` (`'bound'`).
   * - Pressing `slot` when `slot` is bound to a different skill overwrites `slot` (`'bound'`).
   */
  public toggleOrBindSkillHotkey(
    slot: HotkeySlot,
    category: ProactiveSkillCategory,
    skillId: string
  ): 'bound' | 'unbound' | 'invalid' {
    const isLearned =
      category === 'war' ? this.hasWarSkill(skillId) : this.hasMagicSkill(skillId);
    if (!isLearned) {
      return 'invalid';
    }

    const existingOnSlot = this._skillHotkeys[slot];
    if (
      existingOnSlot &&
      existingOnSlot.category === category &&
      existingOnSlot.skillId === skillId
    ) {
      delete this._skillHotkeys[slot];
      return 'unbound';
    }

    for (const otherSlot of ORDERED_HOTKEY_SLOTS) {
      const entry = this._skillHotkeys[otherSlot];
      if (entry && entry.category === category && entry.skillId === skillId) {
        delete this._skillHotkeys[otherSlot];
      }
    }

    this._skillHotkeys[slot] = { category, skillId };
    return 'bound';
  }

  private pruneInvalidSkillHotkeys(): void {
    for (const slot of ORDERED_HOTKEY_SLOTS) {
      const entry = this._skillHotkeys[slot];
      if (!entry) {
        continue;
      }
      const valid =
        entry.category === 'war'
          ? this.hasWarSkill(entry.skillId)
          : this.hasMagicSkill(entry.skillId);
      if (!valid) {
        delete this._skillHotkeys[slot];
      }
    }
  }

  public getCombinedAttributeBonuses(): Partial<PrimaryAttributes> {
    const equipAttrs = this.getTotalEquipmentModifiers().attributeBonuses;
    const soulAttrs = this.getTotalSoulAttributeBonuses();
    const merged: Partial<PrimaryAttributes> = {};
    for (const key of ['str', 'con', 'int', 'wis', 'agi', 'luk'] as PrimaryAttributeKey[]) {
      const val =
        (this.attributeBonuses[key] ?? 0) +
        (equipAttrs[key] ?? 0) +
        (soulAttrs[key] ?? 0);
      if (val !== 0) {
        merged[key] = val;
      }
    }
    return merged;
  }

  /**
   * Equips 1 unit of `inventoryItemId` from `this.inventory` into `slot` (returning any replaced item
   * back to `this.inventory`), preserving current HP/MP/SP while updating derived stats & carry weight.
   */
  public equipItemFromInventory(
    slot: EquipmentSlotId,
    inventoryItemId: string
  ): EquipItemResolution {
    const found = this.inventory.getItems().find((i) => i.id === inventoryItemId);
    if (!found || !canItemFitSlot(found, slot)) {
      return { success: false, equipped: null, unequipped: null };
    }

    const detached = this.inventory.removeItemById(found.id, 1);
    if (!detached || !canItemFitSlot(detached, slot)) {
      return { success: false, equipped: null, unequipped: null };
    }

    const previous = this._equipment[slot];
    this._equipment[slot] = detached;
    if (previous) {
      this.inventory.addItem(previous);
    }

    this._currentCarryWeight = Number(
      (this.inventory.getTotalWeight() + this.getEquippedWeight()).toFixed(2)
    );
    this.recalculateStats(false);
    return {
      success: true,
      equipped: detached,
      unequipped: previous,
    };
  }

  /**
   * Unequips the item currently worn in `slot` back into `this.inventory`, clamping vitals if Max HP/MP/SP decrease.
   */
  public unequipSlotToInventory(slot: EquipmentSlotId): {
    readonly success: boolean;
    readonly unequipped: EquippableItem | null;
  } {
    const previous = this._equipment[slot];
    if (!previous) {
      return { success: false, unequipped: null };
    }
    this._equipment[slot] = null;
    this.inventory.addItem(previous);
    this._currentCarryWeight = Number(
      (this.inventory.getTotalWeight() + this.getEquippedWeight()).toFixed(2)
    );
    this.recalculateStats(false);
    return { success: true, unequipped: previous };
  }

  /**
   * Rolls per-attack melee physical raw damage:
   * - Unarmed (`Weapon` slot empty): rolls `1d2` + `round(STR * 1.5)`
   * - Equipped Weapon: rolls `weaponDice` (`NdS + B`) + `round(STR * 1.5)` + flat `attackBonus`
   */
  public rollMeleePhysicalAttack(rng?: SeededRNG): number {
    if (
      this.customStatOverrides.physicalAttack !== undefined ||
      this.customStatOverrides.attack !== undefined
    ) {
      return this.stats.physicalAttack;
    }
    const dice = this.getEquippedWeaponDice();
    const rolled = rollWeaponDice(dice, rng);
    const equipAttack = this.getTotalEquipmentModifiers().attackBonus;
    const strScaling = Math.round(this.attributes.str * 1.5);
    return Math.max(1, strScaling + rolled + equipAttack);
  }

  /**
   * Un-debuffed attributes (`baseAttributes + attributeBonuses + equipment.attributeBonuses`) prior to percentage status modifiers.
   */
  public get rawAttributes(): PrimaryAttributes {
    const bonuses = this.getCombinedAttributeBonuses();
    return {
      str: Math.max(1, this.baseAttributes.str + (bonuses.str ?? 0)),
      con: Math.max(1, this.baseAttributes.con + (bonuses.con ?? 0)),
      int: Math.max(1, this.baseAttributes.int + (bonuses.int ?? 0)),
      wis: Math.max(1, this.baseAttributes.wis + (bonuses.wis ?? 0)),
      agi: Math.max(1, this.baseAttributes.agi + (bonuses.agi ?? 0)),
      luk: Math.max(1, this.baseAttributes.luk + (bonuses.luk ?? 0)),
    };
  }

  /**
   * Effective PrimaryAttributes after applying Satiety ('weak' -25%, 'faint' -50%) and 'burdened' (-25% AGI) modifiers.
   */
  public get attributes(): PrimaryAttributes {
    return computeEffectiveAttributes(
      this.baseAttributes,
      this.getCombinedAttributeBonuses(),
      this._currentCarryWeight,
      this.satietyState
    ).effectiveAttributes;
  }

