  public get satiety(): number {
    return this._satiety;
  }

  public set satiety(value: number) {
    const clamped = Number(Math.min(MAX_SATIETY, value).toFixed(3));
    const prevState = this.satietyState;
    this._satiety = clamped;
    this._satietyState = this.enableSatiety ? resolveSatietyState(this._satiety) : 'normal';
    const newState = this.satietyState;

    if (prevState !== newState) {
      this.recalculateStats(false);
      if (!this.suppressStatusCallbacks) {
        this.onSatietyStateChange?.({
          previousState: prevState,
          newState,
          satiety: this._satiety,
        });
      }
    }

    if (this.enableSatiety && newState === 'starved' && this.isAlive()) {
      this.stats.hp = 0;
      if (!this.suppressStatusCallbacks) {
        this.onStarvationDeath?.();
      }
    }
  }

  public setSatietySilent(value: number): void {
    const prevSuppress = this.suppressStatusCallbacks;
    this.suppressStatusCallbacks = true;
    try {
      this._satiety = Number(Math.min(MAX_SATIETY, value).toFixed(3));
      this._satietyState = this.enableSatiety ? resolveSatietyState(this._satiety) : 'normal';
      this.recalculateStats(false);
    } finally {
      this.suppressStatusCallbacks = prevSuppress;
    }
  }

  public modifySatiety(delta: number): SatietyState {
    if (!this.enableSatiety || delta === 0) {
      return this.satietyState;
    }
    this.satiety = this._satiety + delta;
    return this.satietyState;
  }

  public get satietyState(): SatietyState {
    return this.enableSatiety ? this._satietyState : 'normal';
  }

  public canEatFood(): boolean {
    return !this.enableSatiety || this.satietyState !== 'full';
  }

  public canDashBySatiety(): boolean {
    if (!this.enableSatiety) {
      return true;
    }
    return (
      this.satietyState !== 'weak' &&
      this.satietyState !== 'faint' &&
      this.satietyState !== 'starved'
    );
  }

