  /**
   * Adds `turns` of Paralysis additively onto any remaining paralysis duration
   * and recalculates stats (`evasion = 0` while paralyzed).
   */
  public addParalysisTurns(turns: number): number {
    const added = Math.max(0, Math.floor(turns));
    if (added <= 0 || !this.isAlive()) {
      return this._paralysisTurns;
    }
    this._paralysisTurns += added;
    this.recalculateStats(false);
    return this._paralysisTurns;
  }

  /**
   * Decrements `paralysisTurns` by 1 turn (clamped at 0) and restores `evasion` when reaching 0.
   */
  public decrementParalysisTurn(): number {
    if (this._paralysisTurns <= 0) {
      return 0;
    }
    this._paralysisTurns = Math.max(0, this._paralysisTurns - 1);
    if (this._paralysisTurns === 0) {
      this.recalculateStats(false);
    }
    return this._paralysisTurns;
  }

