import type { PrimaryAttributeKey, PrimaryAttributes } from '../entities/Actor';
import {
  getLocalizedMagicSkillName,
  getLocalizedWarSkillName,
  getMagicSkillById,
  getWarSkillById,
} from '../skills';

export const DEFAULT_SOUL_DROP_RATE = 0.05;

export interface SerializedAbsorbedSoul {
  readonly soulId: string;
  readonly count: number;
}

export interface SoulDefinition {
  readonly soulId: string;
  readonly nameEn: string;
  readonly nameZh: string;
  readonly spriteKey: string;
  readonly sourceArchetypeId: string;
  readonly sourceEnemyNameEn: string;
  readonly sourceEnemyNameZh: string;
  readonly dropRate: number;
  readonly attributeBonuses?: Partial<PrimaryAttributes>;
  readonly warSkillIds?: readonly string[];
  readonly magicSkillIds?: readonly string[];
  readonly passiveSkillIds?: readonly string[];
  readonly descriptionEn: string;
  readonly descriptionZh: string;
}

const SOUL_REGISTRY = new Map<string, SoulDefinition>();

export function registerSoul(soul: SoulDefinition): void {
  SOUL_REGISTRY.set(soul.soulId, soul);
}

export function getSoulById(soulId: string): SoulDefinition | undefined {
  return SOUL_REGISTRY.get(soulId);
}

export function getAllSouls(): readonly SoulDefinition[] {
  return Array.from(SOUL_REGISTRY.values());
}

export function getLocalizedSoulName(soul: SoulDefinition, lang: 'en' | 'zh-TW'): string {
  return lang === 'zh-TW' ? soul.nameZh : soul.nameEn;
}

const ATTR_LABELS_EN: Record<PrimaryAttributeKey, string> = {
  str: 'STR',
  con: 'CON',
  int: 'INT',
  wis: 'WIS',
  agi: 'AGI',
  luk: 'LUK',
};

const ATTR_LABELS_ZH: Record<PrimaryAttributeKey, string> = {
  str: '力量',
  con: '體質',
  int: '智力',
  wis: '智慧',
  agi: '敏捷',
  luk: '幸運',
};

export function getLocalizedSoulEffectSummary(
  soul: SoulDefinition,
  lang: 'en' | 'zh-TW'
): string {
  const parts: string[] = [];

  if (soul.attributeBonuses) {
    const labels = lang === 'zh-TW' ? ATTR_LABELS_ZH : ATTR_LABELS_EN;
    for (const key of ['str', 'con', 'int', 'wis', 'agi', 'luk'] as PrimaryAttributeKey[]) {
      const val = soul.attributeBonuses[key];
      if (typeof val === 'number' && val !== 0) {
        parts.push(`${labels[key]} ${val > 0 ? '+' : ''}${val}`);
      }
    }
  }

  if (soul.warSkillIds && soul.warSkillIds.length > 0) {
    for (const skillId of soul.warSkillIds) {
      const skill = getWarSkillById(skillId);
      const skillName = skill ? getLocalizedWarSkillName(skill, lang) : skillId;
      parts.push(lang === 'zh-TW' ? `習得戰技：${skillName}` : `War Skill: ${skillName}`);
    }
  }

  if (soul.magicSkillIds && soul.magicSkillIds.length > 0) {
    for (const spellId of soul.magicSkillIds) {
      const spell = getMagicSkillById(spellId);
      const spellName = spell ? getLocalizedMagicSkillName(spell, lang) : spellId;
      parts.push(lang === 'zh-TW' ? `習得魔法：${spellName}` : `Magic Skill: ${spellName}`);
    }
  }

  if (soul.passiveSkillIds && soul.passiveSkillIds.length > 0) {
    for (const passiveId of soul.passiveSkillIds) {
      parts.push(lang === 'zh-TW' ? `被動能力：${passiveId}` : `Passive: ${passiveId}`);
    }
  }

  return parts.join(', ');
}

export function getLocalizedSoulCategoryBadge(
  soul: SoulDefinition,
  lang: 'en' | 'zh-TW'
): string {
  const origin = lang === 'zh-TW' ? soul.sourceEnemyNameZh : soul.sourceEnemyNameEn;
  const effect = getLocalizedSoulEffectSummary(soul, lang);
  if (!origin) {
    if (lang === 'zh-TW') {
      return effect ? `靈魂 · ${effect}` : '靈魂';
    }
    return effect ? `Soul · ${effect}` : 'Soul';
  }
  if (lang === 'zh-TW') {
    return effect ? `靈魂（${origin}）· ${effect}` : `靈魂（${origin}）`;
  }
  return effect ? `Soul (${origin}) · ${effect}` : `Soul (${origin})`;
}

export function getLocalizedSoulDescription(
  soul: SoulDefinition,
  lang: 'en' | 'zh-TW'
): string {
  return lang === 'zh-TW' ? soul.descriptionZh : soul.descriptionEn;
}

