import { Actor } from '../entities/Actor';
import { SeededRNG } from '../SeededRNG';
import { registerPotionType } from './PotionCatalog';
import { PotionItem, PotionItemOptions, PotionQuaffEffectResult } from './PotionItem';

export const DEFAULT_INVISIBILITY_MIN_TURNS = 10;
export const DEFAULT_INVISIBILITY_MAX_TURNS = 20;

export interface InvisibilityPotionOptions extends PotionItemOptions {
  readonly minTurns?: number;
  readonly maxTurns?: number;
}

/**
 * Potion of Invisibility (`隱形藥水`): grants 10–20 character turns of additive Invisible (`invisibleTurns`)
 * on its target when quaffed (+10 Satiety) or thrown.
 */
export class InvisibilityPotion extends PotionItem {
  public readonly minTurns: number;
  public readonly maxTurns: number;

  constructor(options: InvisibilityPotionOptions) {
    const minTurns = Math.max(1, Math.round(options.minTurns ?? DEFAULT_INVISIBILITY_MIN_TURNS));
    const maxTurns = Math.max(
      minTurns,
      Math.round(options.maxTurns ?? DEFAULT_INVISIBILITY_MAX_TURNS)
    );
    super({
      id: options.id ?? `invisibility-potion-${Math.random().toString(36).slice(2, 7)}`,
      name: 'Potion of Invisibility',
      itemTypeId: 'invisibility_potion',
      position: options.position,
      amount: options.amount ?? 1,
      weight: options.weight ?? 0.5,
      stackable: true,
      quaffSatietyBonus: options.quaffSatietyBonus,
      description:
        options.description ??
        `A translucent mist draught that renders its target invisible to others for ${minTurns}–${maxTurns} turns when quaffed or thrown.`,
    });
    this.minTurns = minTurns;
    this.maxTurns = maxTurns;
  }

  public override getIdentifiedStatBadge(lang: 'en' | 'zh-TW'): string {
    return lang === 'zh-TW'
      ? `隱形 ${this.minTurns}–${this.maxTurns}回合`
      : `Invisible ${this.minTurns}–${this.maxTurns}t`;
  }

  public applyToTarget(target: Actor, rng?: SeededRNG): number {
    if (!target.isAlive()) {
      return 0;
    }
    const rolledTurns = rng
      ? rng.nextInt(this.minTurns, this.maxTurns)
      : Math.floor(Math.random() * (this.maxTurns - this.minTurns + 1)) + this.minTurns;
    target.addInvisibleTurns(rolledTurns);
    return rolledTurns;
  }

  public override applyQuaffEffect(target: Actor, rng?: SeededRNG): PotionQuaffEffectResult {
    const added = this.applyToTarget(target, rng);
    return {
      kind: 'invisible',
      observableEffect: added > 0,
      invisibleTurnsAdded: added,
    };
  }

  public override cloneWithAmount(newAmount: number, newId?: string): InvisibilityPotion {
    const cloned = new InvisibilityPotion({
      id: newId ?? `${this.id}-${Math.random().toString(36).slice(2, 7)}`,
      position: { x: this.position.x, y: this.position.y },
      amount: newAmount,
      weight: this.weight,
      description: this.description,
      minTurns: this.minTurns,
      maxTurns: this.maxTurns,
      quaffSatietyBonus: this.quaffSatietyBonus,
    });
    cloned.spriteKey = this.spriteKey;
    return cloned;
  }

  public override serializeCustomData(): Record<string, unknown> {
    return {
      minTurns: this.minTurns,
      maxTurns: this.maxTurns,
    };
  }
}

registerPotionType('invisibility_potion');
